-- 217 (16/11/2026, lô 53): 17 bài Nói TCF cho cây Luyện thi TCF, 66 lượt ghi âm, 6 miễn phí, 11 VIP.
-- Sinh bởi scripts/nhap/lo53_noi_tcf.mjs. Bài ghiAm; AI nhận xét từng lượt bằng nhan-xet-noi (lời nhắc TCF). Chạy lại an toàn.
-- TCF-PO-1 #1 Oral TCF : se présenter à l'examinateur (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo01', 'practice', 'Oral TCF : se présenter à l''examinateur', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 1 du TCF : l''examinateur vous pose des questions sur vous, votre vie et vos projets. Il n''y a pas de préparation. Répondez à chaque question en 3 ou 4 phrases.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un comptable, une comptable : kế toán\n• bruyant (adjectif) : ồn ào\n• la circulation : giao thông\n• immigrer (verbe) : nhập cư\n• faire reconnaître son diplôme : công nhận bằng cấp","explications":"• Đừng trả lời một từ: mỗi câu nói 3 đến 4 câu, có một chi tiết cụ thể (tên, nơi, ví dụ).\n• Câu hỏi về dự định thì dùng futur simple hoặc « je voudrais », « j''aimerais ».","ghiAm":true,"kyNang":"TCF-PO-1","vong":"hoc","thuTu":1}'::jsonb, '2026-11-16T14:00:00.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo01q01', 'lo53tcfpo01', 1, 'open', 'Bonjour. Pouvez-vous vous présenter, s''il vous plaît ?', '{"giay":60}'::jsonb, '{"model":"Bonjour. Je m''appelle Thu, j''ai vingt-huit ans et je suis vietnamienne. J''habite à Hô Chi Minh-Ville avec mon mari et notre petite fille de trois ans. Je travaille comme comptable dans une entreprise d''import-export."}'::jsonb, null),
  ('lo53tcfpo01q02', 'lo53tcfpo01', 2, 'open', 'Où habitez-vous ? Pouvez-vous décrire votre ville ?', '{"giay":60}'::jsonb, '{"model":"J''habite à Hô Chi Minh-Ville, dans le sud du Vietnam. C''est une très grande ville, dynamique et un peu bruyante, avec beaucoup de motos. J''aime surtout ses marchés et sa cuisine de rue, mais la circulation est parfois difficile."}'::jsonb, null),
  ('lo53tcfpo01q03', 'lo53tcfpo01', 3, 'open', 'Qu''est-ce que vous faites dans la vie ?', '{"giay":60}'::jsonb, '{"model":"Je suis comptable. Je prépare les factures et je contrôle les dépenses de l''entreprise. C''est un travail précis qui demande de la patience. Ce que j''apprécie, c''est de travailler avec des clients étrangers."}'::jsonb, null),
  ('lo53tcfpo01q04', 'lo53tcfpo01', 4, 'open', 'Que faites-vous pendant votre temps libre ?', '{"giay":60}'::jsonb, '{"model":"Le week-end, je passe du temps avec ma famille : nous allons au parc ou chez mes parents. J''aime aussi cuisiner et regarder des films français, ça m''aide à progresser. Quand j''ai le temps, je fais du yoga."}'::jsonb, null),
  ('lo53tcfpo01q05', 'lo53tcfpo01', 5, 'open', 'Pourquoi apprenez-vous le français ?', '{"giay":60}'::jsonb, '{"model":"J''apprends le français parce que nous voulons immigrer au Canada, au Québec. Le TCF est obligatoire pour notre dossier. Et puis j''aime cette langue depuis le lycée, je trouve qu''elle est élégante."}'::jsonb, null),
  ('lo53tcfpo01q06', 'lo53tcfpo01', 6, 'open', 'Quels sont vos projets pour les prochaines années ?', '{"giay":60}'::jsonb, '{"model":"Si tout va bien, nous partirons à Montréal dans deux ans. Je voudrais reprendre mes études pour faire reconnaître mon diplôme, puis trouver un poste de comptable. Plus tard, j''aimerais acheter une maison avec un jardin."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-1 #2 Oral TCF : habitudes et souvenirs (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo02', 'practice', 'Oral TCF : habitudes et souvenirs', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 1 du TCF : l''examinateur continue l''entretien et vous pose des questions sur votre quotidien et vos souvenirs. Répondez en 3 ou 4 phrases, avec des exemples.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• être à la retraite : đã nghỉ hưu\n• un frère aîné : anh trai\n• s''entraider (verbe) : giúp đỡ nhau\n• marquer (verbe) : để lại dấu ấn\n• en revanche : ngược lại","explications":"• Kể chuyện đã qua: passé composé cho sự việc, imparfait cho bối cảnh và thói quen.\n• Câu « aimez / n''aimez pas » nên có cả hai vế, nối bằng « en revanche » hoặc « par contre ».","ghiAm":true,"kyNang":"TCF-PO-1","vong":"on","thuTu":2}'::jsonb, '2026-11-16T14:00:01.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo02q01', 'lo53tcfpo02', 1, 'open', 'Parlez-moi de votre famille.', '{"giay":60}'::jsonb, '{"model":"J''ai une petite famille. Mes parents habitent à Huê, ils sont à la retraite. J''ai un frère aîné qui est médecin et qui a deux enfants. Nous nous retrouvons tous ensemble pour le Têt, c''est le moment de l''année que je préfère."}'::jsonb, null),
  ('lo53tcfpo02q02', 'lo53tcfpo02', 2, 'open', 'Comment se passe une journée normale pour vous ?', '{"giay":60}'::jsonb, '{"model":"Je me lève vers six heures et demie, je prépare le petit-déjeuner et j''emmène mon fils à l''école. Je commence le travail à huit heures. Le soir, je rentre vers dix-huit heures, nous dînons, puis j''étudie le français une demi-heure."}'::jsonb, null),
  ('lo53tcfpo02q03', 'lo53tcfpo02', 3, 'open', 'Racontez-moi votre dernier voyage.', '{"giay":60}'::jsonb, '{"model":"L''été dernier, je suis allé à Đà Lạt avec des amis. Il faisait frais, c''était agréable après la chaleur de la ville. Nous avons visité des fermes de fraises et nous avons fait une randonnée autour du lac. J''aimerais y retourner."}'::jsonb, null),
  ('lo53tcfpo02q04', 'lo53tcfpo02', 4, 'open', 'Quel est votre plat préféré ? Pourquoi ?', '{"giay":60}'::jsonb, '{"model":"Mon plat préféré, c''est le phở de ma mère. C''est une soupe de nouilles au bœuf, avec beaucoup d''herbes. Je l''aime parce qu''elle me rappelle mon enfance, les dimanches matin à la maison. J''ai essayé de la préparer, mais ce n''est jamais aussi bon !"}'::jsonb, null),
  ('lo53tcfpo02q05', 'lo53tcfpo02', 5, 'open', 'Quel souvenir d''enfance vous a marqué ?', '{"giay":60}'::jsonb, '{"model":"Quand j''avais huit ans, mon grand-père m''a appris à faire du vélo. Je tombais tout le temps, mais il restait patient. Le jour où j''ai réussi à rouler seul, il était plus fier que moi. Il est mort depuis, mais je pense souvent à ce moment."}'::jsonb, null),
  ('lo53tcfpo02q06', 'lo53tcfpo02', 6, 'open', 'Qu''est-ce que vous aimez et qu''est-ce que vous n''aimez pas dans votre travail ou vos études ?', '{"giay":60}'::jsonb, '{"model":"Dans mon travail, j''aime l''ambiance : mes collègues sont sympathiques et on s''entraide. En revanche, je n''aime pas les longues réunions qui ne servent à rien. Parfois, je dois aussi travailler tard le soir, et c''est fatigant."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-2 #1 Oral TCF : s'inscrire dans une salle de sport (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo03', 'practice', 'Oral TCF : s''inscrire dans une salle de sport', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 2 du TCF. Situation : vous voulez vous inscrire dans une salle de sport près de chez vous. L''examinateur joue le rôle du réceptionniste. Posez-lui des questions pour obtenir toutes les informations utiles. C''est VOUS qui posez les questions.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un renseignement : thông tin\n• un abonnement mensuel / annuel : vé tháng / vé năm\n• les frais d''inscription : phí đăng ký\n• une séance d''essai : buổi tập thử\n• résilier (verbe) : huỷ (hợp đồng)","explications":"• Tâche 2 chấm khả năng ĐẶT CÂU HỎI: đổi kiểu hỏi (Est-ce que…, Quel…, Combien…, Est-il possible de…) để không lặp.\n• Mở bằng lời chào và lý do, kết bằng lời cảm ơn: phần phù hợp tình huống cũng được chấm.","ghiAm":true,"kyNang":"TCF-PO-2","vong":"hoc","thuTu":1}'::jsonb, '2026-11-16T14:00:02.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo03q01', 'lo53tcfpo03', 1, 'open', 'Saluez, présentez votre demande, puis posez des questions sur les horaires d''ouverture et les activités proposées.', '{"giay":90}'::jsonb, '{"model":"Bonjour madame. Je viens d''emménager dans le quartier et je voudrais m''inscrire dans votre salle. Est-ce que je pourrais avoir quelques renseignements ? Quels sont vos horaires d''ouverture ? Est-ce que la salle est ouverte le dimanche ? Et quelles activités proposez-vous ? Il y a des cours collectifs, par exemple du yoga ou de la natation ?"}'::jsonb, null),
  ('lo53tcfpo03q02', 'lo53tcfpo03', 2, 'open', 'Posez des questions sur les prix, les formules d''abonnement et les réductions possibles.', '{"giay":90}'::jsonb, '{"model":"Combien coûte l''abonnement ? Est-ce qu''il y a une différence entre l''abonnement mensuel et l''abonnement annuel ? Les cours collectifs sont-ils compris dans le prix ? Je suis étudiant : est-ce que vous faites des réductions pour les étudiants ? Et est-ce qu''il y a des frais d''inscription ?"}'::jsonb, null),
  ('lo53tcfpo03q03', 'lo53tcfpo03', 3, 'open', 'Posez des questions sur les conditions (certificat médical, séance d''essai, résiliation), puis remerciez et prenez congé.', '{"giay":90}'::jsonb, '{"model":"Est-ce qu''il faut un certificat médical pour s''inscrire ? Est-il possible de faire une séance d''essai gratuite avant de décider ? Et si je déménage, est-ce que je peux arrêter l''abonnement facilement ? Quel est le délai ? Très bien, merci beaucoup pour toutes ces informations. Je reviendrai demain avec mes papiers. Bonne journée !"}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-2 #2 Oral TCF : louer un appartement (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo04', 'practice', 'Oral TCF : louer un appartement', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 2 du TCF. Situation : vous cherchez un appartement à louer et vous appelez une agence immobilière pour une annonce. L''examinateur joue le rôle de l''agent immobilier. Posez-lui des questions pour savoir si l''appartement vous convient.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un deux-pièces : căn hộ hai phòng\n• les charges (nom féminin pluriel) : phí dịch vụ\n• la caution : tiền đặt cọc\n• un garant : người bảo lãnh\n• à proximité : gần đó","explications":"• Chuẩn bị 2 phút: ghi nhanh 4 nhóm câu hỏi (nhà, tiền, giấy tờ, lịch xem) để không cạn ý giữa chừng.\n• Lắng nghe câu trả lời của giám khảo rồi hỏi tiếp từ đó (« Et le chauffage, il est compris ? »).","ghiAm":true,"kyNang":"TCF-PO-2","vong":"on","thuTu":2}'::jsonb, '2026-11-16T14:00:03.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo04q01', 'lo53tcfpo04', 1, 'open', 'Présentez-vous et posez des questions sur le logement : surface, nombre de pièces, étage, équipements, quartier.', '{"giay":90}'::jsonb, '{"model":"Bonjour monsieur, j''appelle au sujet de l''annonce pour le deux-pièces rue Victor-Hugo. Quelle est la surface de l''appartement ? Il est à quel étage ? Est-ce qu''il y a un ascenseur ? La cuisine est-elle équipée ? Et le quartier, il est calme ? Il y a des commerces et une station de métro à proximité ?"}'::jsonb, null),
  ('lo53tcfpo04q02', 'lo53tcfpo04', 2, 'open', 'Posez des questions sur le loyer, les charges, la caution et les documents à fournir.', '{"giay":90}'::jsonb, '{"model":"Quel est le montant du loyer ? Est-ce que les charges sont comprises ? Qu''est-ce qu''elles comprennent exactement, le chauffage et l''eau ? Combien faut-il verser pour la caution ? Et quels documents dois-je fournir pour le dossier ? Est-ce qu''un garant est obligatoire ?"}'::jsonb, null),
  ('lo53tcfpo04q03', 'lo53tcfpo04', 3, 'open', 'Posez des questions sur la visite et la date d''entrée, puis concluez poliment.', '{"giay":90}'::jsonb, '{"model":"L''appartement est disponible à partir de quand ? Est-ce que je pourrais le visiter cette semaine ? Le jeudi après dix-huit heures, est-ce que ça vous conviendrait ? Parfait. À quelle adresse dois-je vous retrouver ? Merci beaucoup, monsieur, à jeudi alors. Au revoir."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-3 #1 Oral TCF : le télétravail pour tous ? (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo05', 'practice', 'Oral TCF : le télétravail pour tous ?', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 3 du TCF. Sujet : « Le télétravail devrait-il devenir la norme ? » Donnez votre opinion de manière claire et argumentée. Il n''y a pas de préparation.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• la norme : chuẩn mực, điều mặc định\n• sans cesse : liên tục\n• être interrompu : bị ngắt quãng\n• une objection : ý phản bác\n• un modèle mixte : mô hình kết hợp","explications":"• Nói lập trường NGAY câu thứ hai: giám khảo cần biết bạn nghĩ gì trước khi nghe lý lẽ.\n• Gặp phản bác thì đồng ý một phần (« C''est vrai, mais… ») rồi kéo về ý mình: đó là kỹ năng được chấm ở tâche 3.","ghiAm":true,"kyNang":"TCF-PO-3","vong":"hoc","thuTu":1}'::jsonb, '2026-11-16T14:00:04.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo05q01', 'lo53tcfpo05', 1, 'open', 'Présentez le sujet, donnez clairement votre position et un premier argument.', '{"giay":90}'::jsonb, '{"model":"On parle beaucoup du télétravail depuis quelques années. Faut-il en faire la norme ? Personnellement, je pense que le télétravail est une bonne chose, mais qu''il ne doit pas remplacer complètement le bureau. Mon premier argument, c''est le temps gagné : beaucoup de salariés passent plus d''une heure par jour dans les transports, et ce temps pourrait servir à se reposer ou à voir sa famille."}'::jsonb, null),
  ('lo53tcfpo05q02', 'lo53tcfpo05', 2, 'open', 'Donnez un deuxième argument, avec un exemple concret (votre expérience ou celle d''un proche).', '{"giay":90}'::jsonb, '{"model":"Ensuite, le télétravail permet souvent d''être plus concentré. Par exemple, ma sœur travaille dans une banque. Au bureau, elle est sans cesse interrompue par des collègues ou des réunions. Depuis qu''elle travaille de chez elle deux jours par semaine, elle dit qu''elle fait en une journée ce qu''elle faisait avant en deux."}'::jsonb, null),
  ('lo53tcfpo05q03', 'lo53tcfpo05', 3, 'open', 'L''examinateur réagit : « Mais beaucoup de salariés se sentent seuls en télétravail. » Répondez à cette objection, puis concluez.', '{"giay":90}'::jsonb, '{"model":"C''est vrai, et c''est pour cela que je ne suis pas pour le télétravail à cent pour cent. L''être humain a besoin de contacts, et les échanges informels au bureau sont importants pour l''équipe. À mon avis, la meilleure solution est un modèle mixte : deux ou trois jours à la maison, le reste au bureau. En conclusion, le télétravail ne doit pas devenir la norme, mais une possibilité offerte à tous."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-3 #2 Oral TCF : des villes sans voitures ? (miễn phí)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo06', 'practice', 'Oral TCF : des villes sans voitures ?', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 3 du TCF. Sujet : « Faut-il interdire la voiture dans le centre des villes ? » Donnez votre opinion de manière claire et argumentée. Il n''y a pas de préparation.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un centre piéton : khu phố đi bộ\n• les maladies respiratoires : bệnh hô hấp\n• un livreur : người giao hàng\n• prévoir des exceptions : dự liệu ngoại lệ\n• une navette : xe đưa đón","explications":"• Dùng từ nối để giám khảo theo kịp: d''abord, ensuite, par exemple, en conclusion.\n• Ví dụ có thật (nơi đã đến, người quen) thuyết phục hơn số liệu bạn không chắc.","ghiAm":true,"kyNang":"TCF-PO-3","vong":"on","thuTu":2}'::jsonb, '2026-11-16T14:00:05.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo06q01', 'lo53tcfpo06', 1, 'open', 'Présentez le sujet, donnez clairement votre position et un premier argument.', '{"giay":90}'::jsonb, '{"model":"Dans beaucoup de grandes villes, on se demande s''il faut interdire les voitures dans le centre. Pour ma part, je suis plutôt favorable à cette idée. D''abord, pour la santé : la pollution de l''air provoque des maladies respiratoires, surtout chez les enfants et les personnes âgées. Moins de voitures, c''est un air plus propre pour tout le monde."}'::jsonb, null),
  ('lo53tcfpo06q02', 'lo53tcfpo06', 2, 'open', 'Donnez un deuxième argument, avec un exemple concret.', '{"giay":90}'::jsonb, '{"model":"Ensuite, un centre sans voitures est plus agréable à vivre. Par exemple, l''année dernière, j''ai visité une ville européenne où le centre est piéton. Les rues étaient calmes, il y avait des terrasses, des enfants qui jouaient, des gens à vélo. Les commerces avaient beaucoup de clients, parce que les gens prenaient le temps de se promener."}'::jsonb, null),
  ('lo53tcfpo06q03', 'lo53tcfpo06', 3, 'open', 'L''examinateur réagit : « Et les personnes âgées, les livreurs, les commerçants ? » Répondez à cette objection, puis concluez.', '{"giay":90}'::jsonb, '{"model":"C''est une bonne question, il ne faut oublier personne. On peut prévoir des exceptions : les livraisons le matin, les taxis, les voitures des personnes handicapées. Il faut aussi développer les transports en commun et les navettes gratuites avant d''interdire. En conclusion, je suis pour un centre sans voitures, mais seulement si la ville propose de vraies solutions pour se déplacer."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-1 #3 Oral TCF : logement et quartier (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo07', 'practice', 'Oral TCF : logement et quartier', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 1 du TCF : l''examinateur vous pose des questions sur votre logement, votre quartier et votre vie quotidienne. Répondez à chaque question en 3 ou 4 phrases.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une pièce : phòng (trong căn hộ)\n• bien équipé (adjectif) : đủ tiện ích\n• le stationnement : việc đỗ xe\n• le ménage : việc dọn nhà\n• à distance : từ xa","explications":"• Mô tả nơi ở: kích thước, số phòng, điều thích, điều chưa thích.\n• Câu về tương lai: « j''aimerais », « je voudrais » + lý do ngắn.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"TCF-PO-1","vong":"on","thuTu":3}'::jsonb, '2026-11-16T14:00:06.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo07q01', 'lo53tcfpo07', 1, 'open', 'Pouvez-vous décrire votre logement ?', '{"giay":60}'::jsonb, '{"model":"J''habite dans un appartement de trois pièces, au cinquième étage d''un immeuble récent. Il y a un salon assez grand, deux chambres et une petite cuisine. Ce que je préfère, c''est le balcon : le soir, on voit toute la ville. Le seul problème, c''est qu''il n''y a pas d''ascenseur."}'::jsonb, null),
  ('lo53tcfpo07q02', 'lo53tcfpo07', 2, 'open', 'Qu''est-ce que vous aimez dans votre quartier ?', '{"giay":60}'::jsonb, '{"model":"Mon quartier est calme mais bien équipé. Il y a un marché deux fois par semaine, une bibliothèque et un grand parc où je cours le dimanche. Les voisins sont sympathiques, on se dit bonjour dans la rue. C''est rare dans une grande ville."}'::jsonb, null),
  ('lo53tcfpo07q03', 'lo53tcfpo07', 3, 'open', 'Comment allez-vous au travail ou à l''école ?', '{"giay":60}'::jsonb, '{"model":"D''habitude, je prends le métro, c''est rapide : vingt minutes environ. Quand il fait beau, je préfère y aller à vélo, ça me fait du sport. Je n''ai pas de voiture, car le stationnement est difficile et cher en ville."}'::jsonb, null),
  ('lo53tcfpo07q04', 'lo53tcfpo07', 4, 'open', 'Que faites-vous le week-end ?', '{"giay":60}'::jsonb, '{"model":"Le samedi matin, je fais les courses et le ménage. L''après-midi, je retrouve souvent des amis pour boire un café ou voir un film. Le dimanche, je me repose et j''appelle ma famille au Vietnam par vidéo. Parfois, nous partons à la campagne."}'::jsonb, null),
  ('lo53tcfpo07q05', 'lo53tcfpo07', 5, 'open', 'Est-ce que vous aimez cuisiner ?', '{"giay":60}'::jsonb, '{"model":"Oui, beaucoup ! Je cuisine presque tous les soirs, surtout des plats vietnamiens, comme les nems ou la soupe de nouilles. Depuis que j''habite en France, j''apprends aussi des recettes françaises. Ma spécialité maintenant, c''est la quiche aux légumes."}'::jsonb, null),
  ('lo53tcfpo07q06', 'lo53tcfpo07', 6, 'open', 'Où aimeriez-vous habiter dans dix ans ?', '{"giay":60}'::jsonb, '{"model":"Dans dix ans, j''aimerais habiter dans une petite ville près de la mer, peut-être en Bretagne. Je voudrais une maison avec un jardin pour cultiver des légumes. La vie y est plus calme, et je pourrais travailler en partie à distance."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-1 #4 Oral TCF : études et travail (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo08', 'practice', 'Oral TCF : études et travail', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 1 du TCF : l''examinateur vous pose des questions sur vos études, votre travail et vos compétences. Répondez à chaque question en 3 ou 4 phrases, avec des exemples.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un master : bằng thạc sĩ\n• respecter les délais : đúng hạn\n• enrichissant (adjectif) : bổ ích\n• une responsabilité : trách nhiệm\n• rêver de : mơ ước","explications":"• Câu về phẩm chất: nêu phẩm chất + một ví dụ cụ thể chứng minh.\n• Câu về tuổi thơ: imparfait (« je voulais », « je regardais »).","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"TCF-PO-1","vong":"on","thuTu":4}'::jsonb, '2026-11-16T14:00:07.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo08q01', 'lo53tcfpo08', 1, 'open', 'Quelles études avez-vous faites ?', '{"giay":60}'::jsonb, '{"model":"J''ai fait des études d''économie à l''université de Hanoï pendant quatre ans. Ensuite, j''ai obtenu un master en gestion. Ce que j''ai le plus aimé, ce sont les projets en groupe avec des entreprises réelles. Ils m''ont appris à travailler en équipe."}'::jsonb, null),
  ('lo53tcfpo08q02', 'lo53tcfpo08', 2, 'open', 'Pouvez-vous décrire une journée de travail typique ?', '{"giay":60}'::jsonb, '{"model":"J''arrive au bureau vers huit heures et je commence par lire mes courriels. Le matin, j''ai souvent des réunions avec mon équipe. L''après-midi, je prépare des rapports et je parle avec des clients au téléphone. Je finis généralement vers dix-huit heures."}'::jsonb, null),
  ('lo53tcfpo08q03', 'lo53tcfpo08', 3, 'open', 'Quelles sont vos qualités principales au travail ?', '{"giay":60}'::jsonb, '{"model":"Je pense que je suis organisée et patiente. Je prépare toujours une liste des tâches pour la journée, et je respecte les délais. Mes collègues disent aussi que je sais écouter. Par contre, je dois apprendre à dire non quand on me demande trop de choses."}'::jsonb, null),
  ('lo53tcfpo08q04', 'lo53tcfpo08', 4, 'open', 'Avez-vous déjà travaillé avec des personnes d''autres pays ?', '{"giay":60}'::jsonb, '{"model":"Oui, dans mon entreprise actuelle, l''équipe est très internationale : il y a des Français, des Canadiens et des Marocains. Au début, c''était difficile de comprendre les différentes façons de travailler. Mais c''est très enrichissant, j''apprends beaucoup de choses chaque jour."}'::jsonb, null),
  ('lo53tcfpo08q05', 'lo53tcfpo08', 5, 'open', 'Qu''est-ce qui est le plus important pour vous dans un emploi ?', '{"giay":60}'::jsonb, '{"model":"Pour moi, le plus important, c''est l''ambiance entre collègues. Un bon salaire, c''est bien, mais si on n''est pas heureux au travail, on se fatigue vite. J''aime aussi avoir des responsabilités et apprendre de nouvelles choses régulièrement."}'::jsonb, null),
  ('lo53tcfpo08q06', 'lo53tcfpo08', 6, 'open', 'Quel métier rêviez-vous de faire quand vous étiez enfant ?', '{"giay":60}'::jsonb, '{"model":"Quand j''étais petite, je voulais être pilote d''avion. Je regardais les avions passer au-dessus de notre maison et je rêvais de voyager partout. Finalement, je suis devenue comptable, mais je voyage beaucoup pendant mes vacances. Le rêve n''est pas complètement perdu !"}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-1 #5 Oral TCF : entretien complet, révision (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo09', 'practice', 'Oral TCF : entretien complet, révision', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 1 du TCF : l''examinateur mène un entretien complet de deux minutes. Répondez naturellement, en développant chaque réponse.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une occasion : cơ hội\n• manquer à quelqu''un : (ai) nhớ\n• un obstacle : trở ngại\n• les démarches administratives : thủ tục hành chính\n• passionné de : đam mê","explications":"• Bài ôn: nói liên tục, mỗi câu khoảng 20 giây; giám khảo thật sẽ hỏi tiếp từ câu bạn vừa nói.\n• « X me manque » (tôi nhớ X): chủ ngữ là thứ mình nhớ, dễ nhầm.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"TCF-PO-1","vong":"chot","thuTu":5}'::jsonb, '2026-11-16T14:00:08.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo09q01', 'lo53tcfpo09', 1, 'open', 'Bonjour. Présentez-vous en quelques mots.', '{"giay":60}'::jsonb, '{"model":"Bonjour. Je m''appelle Minh, j''ai trente-cinq ans et je suis né à Đà Nẵng, au Vietnam. Je suis marié et j''ai deux enfants. Je travaille comme technicien informatique dans une entreprise de logiciels. J''habite à Lyon depuis trois ans."}'::jsonb, null),
  ('lo53tcfpo09q02', 'lo53tcfpo09', 2, 'open', 'Pourquoi avez-vous choisi de vivre en France ?', '{"giay":60}'::jsonb, '{"model":"Mon entreprise m''a proposé un poste à Lyon il y a trois ans, et c''était une belle occasion de découvrir un autre pays. Ma femme était aussi intéressée par la culture française. Aujourd''hui, nous nous sentons bien ici, même si notre famille nous manque."}'::jsonb, null),
  ('lo53tcfpo09q03', 'lo53tcfpo09', 3, 'open', 'Quelles difficultés avez-vous rencontrées à votre arrivée ?', '{"giay":60}'::jsonb, '{"model":"Au début, la langue était le plus grand obstacle : je comprenais mal les gens qui parlaient vite. Les démarches administratives étaient aussi compliquées, surtout pour trouver un logement. Heureusement, des collègues m''ont beaucoup aidé."}'::jsonb, null),
  ('lo53tcfpo09q04', 'lo53tcfpo09', 4, 'open', 'Qu''est-ce qui vous manque de votre pays ?', '{"giay":60}'::jsonb, '{"model":"Ce qui me manque le plus, c''est ma famille, bien sûr, et aussi la nourriture de rue. À Đà Nẵng, on peut manger un bol de soupe délicieux pour presque rien à n''importe quelle heure. Ici, je cuisine moi-même, mais ce n''est pas pareil."}'::jsonb, null),
  ('lo53tcfpo09q05', 'lo53tcfpo09', 5, 'open', 'Avez-vous des loisirs ou des passions ?', '{"giay":60}'::jsonb, '{"model":"Je suis passionné de photographie. Le week-end, je me promène avec mon appareil et je prends des photos de la ville, surtout des vieux quartiers. J''ai même participé à une petite exposition l''année dernière avec un club de photographes amateurs."}'::jsonb, null),
  ('lo53tcfpo09q06', 'lo53tcfpo09', 6, 'open', 'Comment voyez-vous votre avenir ?', '{"giay":60}'::jsonb, '{"model":"J''espère obtenir la nationalité française dans quelques années, c''est pour cela que je passe le TCF. Professionnellement, j''aimerais devenir chef de projet. Et pour mes enfants, je souhaite qu''ils grandissent en parlant le français et le vietnamien."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-2 #3 Oral TCF : organiser un voyage (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo10', 'practice', 'Oral TCF : organiser un voyage', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 2 du TCF. Situation : vous voulez partir quatre jours en voyage organisé et vous entrez dans une agence de voyages. L''examinateur joue le rôle de l''employé de l''agence. Posez-lui des questions pour obtenir toutes les informations utiles. C''est VOUS qui posez les questions.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un voyage organisé : tour du lịch\n• la demi-pension : bao hai bữa\n• la pension complète : bao ba bữa\n• annuler sans frais : huỷ không mất phí\n• payer en plusieurs fois : trả góp","explications":"• Nhóm câu hỏi theo chủ đề (điểm đến, giá, điều kiện) để không lặp lại.\n• Câu hỏi « Est-ce que… compris ? » rất hữu ích khi hỏi giá.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"TCF-PO-2","vong":"hoc","thuTu":3}'::jsonb, '2026-11-16T14:00:09.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo10q01', 'lo53tcfpo10', 1, 'open', 'Saluez, expliquez votre projet, puis posez des questions sur les destinations et les dates possibles.', '{"giay":90}'::jsonb, '{"model":"Bonjour monsieur. Je voudrais partir quatre jours en voyage organisé, en mai, avec mon mari. Quelles destinations est-ce que vous proposez pour cette période ? Est-ce qu''il y a des voyages en Europe, par exemple en Italie ou en Espagne ? Et quelles sont les dates de départ possibles ?"}'::jsonb, null),
  ('lo53tcfpo10q02', 'lo53tcfpo10', 2, 'open', 'Posez des questions sur le prix, ce qui est compris (transport, hôtel, repas) et les réductions.', '{"giay":90}'::jsonb, '{"model":"Combien coûte ce voyage par personne ? Est-ce que le vol et l''hôtel sont compris dans le prix ? Et les repas, c''est en demi-pension ou en pension complète ? Est-ce qu''il y a des visites guidées incluses ? Faites-vous une réduction si on réserve deux mois à l''avance ?"}'::jsonb, null),
  ('lo53tcfpo10q03', 'lo53tcfpo10', 3, 'open', 'Posez des questions sur les conditions d''annulation et le paiement, puis concluez poliment.', '{"giay":90}'::jsonb, '{"model":"Si nous devons annuler, est-ce que nous serons remboursés ? Jusqu''à quelle date peut-on annuler sans frais ? Est-ce qu''il est possible de payer en plusieurs fois ? Très bien, merci pour toutes ces informations. Je vais en parler avec mon mari et je vous rappelle demain. Au revoir, monsieur."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-2 #4 Oral TCF : s'inscrire à l'université (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo11', 'practice', 'Oral TCF : s''inscrire à l''université', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 2 du TCF. Situation : vous voulez vous inscrire à un cours de français à l''université pour adultes. Vous allez au bureau des inscriptions. L''examinateur joue le rôle de la secrétaire. Posez-lui des questions pour obtenir toutes les informations utiles. C''est VOUS qui posez les questions.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un test de niveau : bài kiểm tra trình độ\n• une session : khoá học, đợt\n• un demandeur d''emploi : người tìm việc\n• un justificatif de domicile : giấy tờ chứng minh nơi ở\n• un dossier : hồ sơ","explications":"• Nói hoàn cảnh của mình (« Je travaille la journée ») trước khi hỏi giúp câu hỏi tự nhiên.\n• Cuối mỗi lượt có thể hỏi thêm một câu tiếp nối từ câu trả lời của giám khảo.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"TCF-PO-2","vong":"on","thuTu":4}'::jsonb, '2026-11-16T14:00:10.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo11q01', 'lo53tcfpo11', 1, 'open', 'Présentez-vous et posez des questions sur les niveaux et le contenu des cours.', '{"giay":90}'::jsonb, '{"model":"Bonjour madame. Je m''appelle Lan et je voudrais m''inscrire à un cours de français pour adultes. Quels niveaux proposez-vous ? Est-ce qu''il faut passer un test avant de s''inscrire ? Et dans les cours, on travaille surtout l''oral ou aussi l''écrit ? Est-ce qu''il y a une préparation au TCF ?"}'::jsonb, null),
  ('lo53tcfpo11q02', 'lo53tcfpo11', 2, 'open', 'Posez des questions sur les horaires, la durée et le nombre d''étudiants par classe.', '{"giay":90}'::jsonb, '{"model":"Les cours ont lieu à quels moments de la semaine ? Je travaille la journée : est-ce qu''il y a des cours le soir ou le samedi ? Combien d''heures par semaine faut-il compter ? La session dure combien de temps ? Et combien d''étudiants y a-t-il dans chaque groupe ?"}'::jsonb, null),
  ('lo53tcfpo11q03', 'lo53tcfpo11', 3, 'open', 'Posez des questions sur le prix, les aides possibles et les documents à fournir, puis remerciez.', '{"giay":90}'::jsonb, '{"model":"Quel est le prix de la session ? Est-ce qu''il existe des aides ou des réductions pour les demandeurs d''emploi ? Quels documents dois-je apporter pour l''inscription ? Une pièce d''identité suffit, ou faut-il aussi un justificatif de domicile ? Parfait, merci beaucoup, madame. Je reviens lundi avec mon dossier."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-2 #5 Oral TCF : adopter un animal (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo12', 'practice', 'Oral TCF : adopter un animal', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 2 du TCF. Situation : vous voulez adopter un chien dans un refuge pour animaux. L''examinateur joue le rôle du bénévole du refuge. Posez-lui des questions pour obtenir toutes les informations utiles. C''est VOUS qui posez les questions.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un refuge : trại cứu hộ\n• à mi-temps : bán thời gian\n• vacciné (adjectif) : đã tiêm phòng\n• aboyer (verbe) : sủa\n• les frais d''adoption : phí nhận nuôi","explications":"• Đặt câu hỏi phù hợp hoàn cảnh mình đã nêu (căn hộ nhỏ → chó nhỏ, ở một mình được không).\n• Đa dạng câu hỏi: đảo ngữ (« Est-il vacciné ? »), « Est-ce que », từ để hỏi.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"TCF-PO-2","vong":"on","thuTu":5}'::jsonb, '2026-11-16T14:00:11.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo12q01', 'lo53tcfpo12', 1, 'open', 'Saluez, présentez votre situation, puis posez des questions sur les chiens disponibles.', '{"giay":90}'::jsonb, '{"model":"Bonjour. J''aimerais adopter un chien. J''habite dans un appartement avec un petit balcon, et je travaille à mi-temps. Quels chiens avez-vous en ce moment ? Est-ce qu''il y a des chiens de petite taille, calmes, qui s''entendent bien avec les enfants ? Quel âge ont-ils ?"}'::jsonb, null),
  ('lo53tcfpo12q02', 'lo53tcfpo12', 2, 'open', 'Posez des questions sur la santé, le caractère et les besoins du chien choisi.', '{"giay":90}'::jsonb, '{"model":"Ce chien est-il en bonne santé ? Est-ce qu''il est vacciné et identifié ? Quel est son caractère : il aboie beaucoup ? Est-ce qu''il supporte de rester seul quelques heures ? Combien de promenades faut-il prévoir par jour ? Et qu''est-ce qu''il mange ?"}'::jsonb, null),
  ('lo53tcfpo12q03', 'lo53tcfpo12', 3, 'open', 'Posez des questions sur la procédure d''adoption et le coût, puis concluez.', '{"giay":90}'::jsonb, '{"model":"Comment se passe l''adoption ? Faut-il remplir un dossier ou avoir un entretien ? Est-ce qu''il y a des frais d''adoption ? Si cela se passe mal, est-ce qu''on peut vous le ramener ? Merci beaucoup pour vos explications. Est-ce que je peux revenir samedi avec ma fille pour le rencontrer ? Au revoir !"}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-2 #6 Oral TCF : réparer son téléphone (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo13', 'practice', 'Oral TCF : réparer son téléphone', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 2 du TCF. Situation : l''écran de votre téléphone est cassé. Vous entrez dans un magasin de réparation. L''examinateur joue le rôle du réparateur. Posez-lui des questions pour obtenir toutes les informations utiles. C''est VOUS qui posez les questions.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• un écran cassé : màn hình vỡ\n• le tactile : cảm ứng\n• une pièce d''origine : linh kiện chính hãng\n• une garantie : bảo hành\n• les données personnelles : dữ liệu cá nhân","explications":"• Kết lượt cuối bằng một QUYẾT ĐỊNH (« je choisis… ») cho thấy bạn đã dùng thông tin nhận được.\n• Tâche 2 chấm sự phong phú câu hỏi: tránh lặp « Est-ce que » liên tục.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"TCF-PO-2","vong":"chot","thuTu":6}'::jsonb, '2026-11-16T14:00:12.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo13q01', 'lo53tcfpo13', 1, 'open', 'Expliquez le problème et posez des questions sur la réparation possible et sa durée.', '{"giay":90}'::jsonb, '{"model":"Bonjour. Mon téléphone est tombé hier et l''écran est cassé. Le tactile fonctionne encore un peu, mais on voit mal. Est-ce que vous pouvez le réparer ? Vous avez la pièce en stock pour ce modèle ? Combien de temps dure la réparation ? Je peux attendre sur place ?"}'::jsonb, null),
  ('lo53tcfpo13q02', 'lo53tcfpo13', 2, 'open', 'Posez des questions sur le prix, la garantie et la qualité des pièces.', '{"giay":90}'::jsonb, '{"model":"Combien coûte le changement d''écran ? Est-ce que c''est une pièce d''origine ou une pièce compatible ? Y a-t-il une différence de prix entre les deux ? La réparation est-elle garantie ? Pendant combien de temps ? Et si le problème revient, je dois payer à nouveau ?"}'::jsonb, null),
  ('lo53tcfpo13q03', 'lo53tcfpo13', 3, 'open', 'Posez des questions sur vos données personnelles et le paiement, puis prenez une décision et concluez.', '{"giay":90}'::jsonb, '{"model":"Est-ce que je risque de perdre mes photos et mes contacts pendant la réparation ? Dois-je vous donner mon code ? Est-ce que je peux payer par carte ? D''accord, je choisis la pièce d''origine avec la garantie d''un an. Je reviens le chercher à dix-sept heures. Merci beaucoup !"}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-3 #3 Oral TCF : l'uniforme scolaire (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo14', 'practice', 'Oral TCF : l''uniforme scolaire', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 3 du TCF. Sujet : « L''uniforme devrait-il être obligatoire à l''école ? » Donnez votre opinion de manière claire et argumentée. Il n''y a pas de préparation.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une tenue : trang phục\n• exclu (adjectif) : bị loại ra ngoài\n• un sentiment d''appartenance : cảm giác thuộc về\n• la scolarité : thời đi học\n• un inconvénient : bất lợi","explications":"• Đáp phản bác: thừa nhận (« C''est vrai ») → giới hạn (« Mais… ne se limite pas à… ») → kết.\n• Kết luận có điều kiện (« à condition que… ») cho thấy lập luận cân nhắc.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"TCF-PO-3","vong":"hoc","thuTu":3}'::jsonb, '2026-11-16T14:00:13.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo14q01', 'lo53tcfpo14', 1, 'open', 'Présentez le sujet, donnez clairement votre position et un premier argument.', '{"giay":90}'::jsonb, '{"model":"La question de l''uniforme à l''école revient régulièrement en débat. Pour ma part, je suis plutôt favorable à l''uniforme. Mon premier argument, c''est l''égalité : quand tout le monde porte la même tenue, on ne juge plus les élèves sur les marques de leurs vêtements, et les familles modestes ne se sentent pas exclues."}'::jsonb, null),
  ('lo53tcfpo14q02', 'lo53tcfpo14', 2, 'open', 'Donnez un deuxième argument, avec un exemple concret.', '{"giay":90}'::jsonb, '{"model":"Ensuite, l''uniforme crée un sentiment d''appartenance. Par exemple, au Vietnam, j''ai porté l''uniforme pendant toute ma scolarité. Nous étions fiers de représenter notre école lors des compétitions. Et le matin, je ne perdais pas de temps à choisir mes vêtements, je pouvais me concentrer sur mes cours."}'::jsonb, null),
  ('lo53tcfpo14q03', 'lo53tcfpo14', 3, 'open', 'L''examinateur réagit : « Mais les adolescents ont besoin d''exprimer leur personnalité. » Répondez, puis concluez.', '{"giay":90}'::jsonb, '{"model":"C''est vrai, l''adolescence est une période où l''on construit son identité. Mais la personnalité ne se limite pas aux vêtements : elle s''exprime par les idées, les activités, les amitiés. Et en dehors de l''école, chacun reste libre de s''habiller comme il veut. En conclusion, je pense que l''uniforme apporte plus d''avantages que d''inconvénients, à condition qu''il soit simple et peu cher."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-3 #4 Oral TCF : vivre en ville ou à la campagne (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo15', 'practice', 'Oral TCF : vivre en ville ou à la campagne', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 3 du TCF. Sujet : « Vaut-il mieux vivre en ville ou à la campagne ? » Donnez votre opinion de manière claire et argumentée. Il n''y a pas de préparation.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• l''accès aux services : khả năng tiếp cận dịch vụ\n• une offre d''emploi : cơ hội việc làm\n• compenser (verbe) : bù lại\n• la retraite : nghỉ hưu\n• une personne active : người đang đi làm","explications":"• « du moins à cette période de ma vie » giúp ý kiến tinh tế, không tuyệt đối.\n• Nói cách mình bù lại điểm yếu (« j''essaie de compenser ») là câu trả lời phản bác hay.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"TCF-PO-3","vong":"on","thuTu":4}'::jsonb, '2026-11-16T14:00:14.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo15q01', 'lo53tcfpo15', 1, 'open', 'Présentez le sujet, donnez clairement votre position et un premier argument.', '{"giay":90}'::jsonb, '{"model":"Beaucoup de gens se demandent aujourd''hui s''il vaut mieux vivre en ville ou à la campagne. Personnellement, je préfère la ville, du moins à cette période de ma vie. Mon premier argument, c''est l''accès aux services : en ville, on trouve facilement un hôpital, des écoles, des transports et des offres d''emploi variées."}'::jsonb, null),
  ('lo53tcfpo15q02', 'lo53tcfpo15', 2, 'open', 'Donnez un deuxième argument, avec un exemple concret.', '{"giay":90}'::jsonb, '{"model":"Ensuite, la ville offre une vie culturelle très riche. Par exemple, à Lyon, je peux aller au cinéma, au théâtre ou à un concert plusieurs fois par mois, souvent à pied. Mes cousins qui vivent à la campagne doivent faire une heure de voiture pour voir un spectacle, alors ils sortent rarement."}'::jsonb, null),
  ('lo53tcfpo15q03', 'lo53tcfpo15', 3, 'open', 'L''examinateur réagit : « Mais en ville, il y a la pollution, le bruit et le stress. » Répondez, puis concluez.', '{"giay":90}'::jsonb, '{"model":"Je suis d''accord, ce sont de vrais inconvénients. C''est pourquoi j''essaie de compenser : je vais dans les parcs, je fais du vélo, et je pars à la campagne le week-end quand je peux. Je pense aussi qu''après la retraite, je choisirai peut-être une vie plus calme. En conclusion, le meilleur choix dépend de l''âge et des besoins de chacun, mais pour une personne active, la ville reste plus pratique."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-3 #5 Oral TCF : apprendre avec l'intelligence artificielle (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo16', 'practice', 'Oral TCF : apprendre avec l''intelligence artificielle', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 3 du TCF. Sujet : « Les élèves devraient-ils pouvoir utiliser l''intelligence artificielle pour faire leurs devoirs ? » Donnez votre opinion de manière claire et argumentée. Il n''y a pas de préparation.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• une notion : khái niệm\n• un professeur particulier : gia sư\n• évaluer (verbe) : đánh giá\n• le raisonnement : lập luận\n• une béquille : cái nạng (chỗ dựa)","explications":"• Ý kiến « oui, mais avec des règles » cho phép bạn trả lời phản bác dễ dàng.\n• Đề xuất giải pháp (thay cách đánh giá) mạnh hơn chỉ phủ nhận phản bác.","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"TCF-PO-3","vong":"on","thuTu":5}'::jsonb, '2026-11-16T14:00:15.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo16q01', 'lo53tcfpo16', 1, 'open', 'Présentez le sujet, donnez clairement votre position et un premier argument.', '{"giay":90}'::jsonb, '{"model":"Avec l''arrivée des outils d''intelligence artificielle, beaucoup d''élèves les utilisent pour leurs devoirs. Faut-il l''autoriser ? À mon avis, oui, mais avec des règles. Mon premier argument, c''est que ces outils peuvent expliquer une notion difficile de plusieurs façons, comme un professeur particulier disponible à toute heure."}'::jsonb, null),
  ('lo53tcfpo16q02', 'lo53tcfpo16', 2, 'open', 'Donnez un deuxième argument, avec un exemple concret.', '{"giay":90}'::jsonb, '{"model":"Ensuite, les élèves vont utiliser ces outils dans leur futur travail, donc il vaut mieux leur apprendre à s''en servir intelligemment. Par exemple, mon neveu utilise une application pour vérifier ses exercices de mathématiques. Quand il se trompe, l''outil ne donne pas la réponse, il l''aide à trouver son erreur. Il a beaucoup progressé."}'::jsonb, null),
  ('lo53tcfpo16q03', 'lo53tcfpo16', 3, 'open', 'L''examinateur réagit : « Mais certains élèves vont simplement copier les réponses sans réfléchir. » Répondez, puis concluez.', '{"giay":90}'::jsonb, '{"model":"C''est un vrai risque, je le reconnais. C''est pour cela que les professeurs doivent changer leur façon d''évaluer : plus d''exercices en classe, plus d''oral, où l''élève doit expliquer son raisonnement. Copier ne sert à rien si l''on doit ensuite justifier sa réponse. En conclusion, interdire ces outils serait inutile ; il vaut mieux apprendre aux élèves à les utiliser comme une aide, et non comme une béquille."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);

-- TCF-PO-3 #6 Oral TCF : le bénévolat obligatoire ? (VIP)
with e as (insert into public.exercises (id, store, title, level, skills, usage_type, deadline, time_limit, consigne, reading_text, audio_url, image_url, meta, created_at) values ('lo53tcfpo17', 'practice', 'Oral TCF : le bénévolat obligatoire ?', 'TCF', array['Production orale']::text[], 'practice', null, null, '<p>Tâche 3 du TCF. Sujet : « Faut-il rendre le bénévolat obligatoire pour les jeunes ? » Donnez votre opinion de manière claire et argumentée. Il n''y a pas de préparation.</p><p><strong>Comme au TCF :</strong> parlez sans lire. Enregistrez une réponse pour chaque étape ; l''IA commente chaque enregistrement, puis vous pouvez écouter une réponse modèle.</p>', null, null, null, '{"targeted":false,"assignedTo":[],"assignedClasses":[],"assignedExtra":[],"vocabulaire":"• le bénévolat : công việc tình nguyện\n• la volonté : ý chí, sự tự nguyện\n• une corvée : việc vặt bắt buộc\n• forcé (adjectif) : bị ép buộc\n• l''engagement (nom masculin) : sự dấn thân","explications":"• Đứng phía phản đối vẫn nên tỏ ra hiểu giá trị của vấn đề (« même si j''apprécie… »).\n• Câu kết hay đối lập hai động từ: « encourager plutôt que imposer ».","ghiAm":true,"isPremium":true,"price":19000,"kyNang":"TCF-PO-3","vong":"chot","thuTu":6}'::jsonb, '2026-11-16T14:00:16.000Z') on conflict (id) do nothing returning id)
insert into public.questions (id, exercise_id, ord, type, prompt, payload, answer_key, explanation)
select v.* from e, (values
  ('lo53tcfpo17q01', 'lo53tcfpo17', 1, 'open', 'Présentez le sujet, donnez clairement votre position et un premier argument.', '{"giay":90}'::jsonb, '{"model":"Certains proposent d''obliger les jeunes à faire quelques semaines de bénévolat, par exemple dans une association. Je suis plutôt contre l''obligation, même si j''apprécie beaucoup le bénévolat. Mon premier argument, c''est que le bénévolat repose sur la volonté : si on l''impose, il perd son sens et devient une simple corvée."}'::jsonb, null),
  ('lo53tcfpo17q02', 'lo53tcfpo17', 2, 'open', 'Donnez un deuxième argument, avec un exemple concret.', '{"giay":90}'::jsonb, '{"model":"Ensuite, les associations ont besoin de personnes motivées. Par exemple, ma sœur est responsable dans une association d''aide aux devoirs. Elle m''a raconté qu''un lycéen envoyé par son école arrivait toujours en retard et regardait son téléphone. Il ne voulait pas être là, et les enfants le sentaient. Un bénévole forcé peut faire plus de mal que de bien."}'::jsonb, null),
  ('lo53tcfpo17q03', 'lo53tcfpo17', 3, 'open', 'L''examinateur réagit : « Mais sans obligation, beaucoup de jeunes ne découvriront jamais le bénévolat. » Répondez, puis concluez.', '{"giay":90}'::jsonb, '{"model":"C''est un argument juste : beaucoup de jeunes ne connaissent pas les associations. Mais la solution, c''est de faire découvrir, pas d''obliger. L''école pourrait organiser des rencontres avec des associations, ou proposer une journée de découverte. Ceux qui aiment continueront d''eux-mêmes. En conclusion, je préfère encourager l''engagement plutôt que de l''imposer, car un engagement choisi dure plus longtemps."}'::jsonb, null)
) as v(id, exercise_id, ord, type, prompt, payload, answer_key, explanation);
